import{_ as n,o as t,c as m,y as e}from"./chunks/framework.CNTkXYA8.js";const l=JSON.parse('{"title":"【OI】关于斯特林数的简单理解","description":"","frontmatter":{"title":"【OI】关于斯特林数的简单理解","date":"2019-02-17T11:08:00.000Z"},"headers":[],"relativePath":"blog/post-10390453.md","filePath":"source/old_posts/post-10390453.md"}'),o={name:"blog/post-10390453.md"};function S(s,p,a,_,r,c){return t(),m("div",null,[...p[0]||(p[0]=[e("<p>斯特林数分为第一类斯特林数：S1(n,k)和第二类斯特林数：S2(n,k)。</p><p>S1(n,k)代表在n个元素中选出k个环的方案数，S2(n,k)代表在n个元素中选出k个非空集合的方案数，</p><p>不同之处在于，在第一类斯特林数中我们在意这些环的顺序，在第二类斯特林数中我们不在意顺序，但在意集合中装了什么（感觉类似排列组合中的有序组合(P)和无序组合(C)）。</p><p>第一类斯特林数的公式是：</p><p>S1(n,m)=(n-1)*S1(n-1,m)+S1(n-1,m-1)</p><p>如何推导出这些：</p><p>我们在n-1的时候可能有两种状态：</p><p>1.已有m个环， 从某个元素数&gt;1的环中加入一个元素，转移到m个环的状态，环有顺序，共有n-1个元素，所以可以插入到任意一个元素的左边，因此有n-1个种可能</p><p>2.已有m-1个环，直接把这个元素作为一个新环，转移到m个环的状态，因为只加入一个环，所以没有其他状态</p><p>根据状态1得到(n-1)*S1(n-1,m)；根据状态2得到S1(n-1,m-1)，合起来就是第一类斯特林数公式：S1(n,m)=(n-1)*S1(n-1,m)+S1(n-1,m-1)</p><p>第二类斯特林数的公式是：</p><p>S2(n,m)=m*S2(n-1,m)+S2(n-1,m-1)</p><p>如何推导出这些：</p><p>在n-1的时候可能有两种状态：</p><p>1.已有m个集合，因为不考虑顺序，可以插入m个集合中任意的集合，所以有m种可能</p><p>2.已有m-1个集合，直接把这个元素作为一个新集合，没有其它状态</p><p>根据状态1得到m*S1(n-1,m)；根据状态2得到S1(n-1,m-1)，合起来就是第二类斯特林数公式：S2(n,m)=m*S2(n-1,m)+S2(n-1,m-1)</p>",17)])])}const i=n(o,[["render",S]]);export{l as __pageData,i as default};
